const inp = $workflow.input || {};
const src = inp.requestSource || 'FraudAndBureauScreen';
const scenario = inp.scenario || 'Standard';
const runId = inp.runId || 'RUN-0001';
const claimReference = inp.claimReference || '';

const FRAUD_SCORES = {
  Standard: 20,
  Displaced: 25,
  Underinsured: 22,
  Investigated: 82,
  Declined: 24,
  Reopened: 20
};

const fraudScore = (FRAUD_SCORES[scenario] !== undefined) ? FRAUD_SCORES[scenario] : FRAUD_SCORES.Standard;

const out = {
  fraudScore: 0,
  litigationEventCode: '',
  claimStatus: '',
  decisionRationale: '',
  explanation: ''
};

if (src === 'FraudAndBureauScreen') {
  out.fraudScore = fraudScore;
  out.litigationEventCode = '';
  out.explanation = 'Claims register and injury bureau screen returned a score of ' + fraudScore + (fraudScore >= 75 ? '; the claim is referred to the investigation lane.' : '; no referral required.');
} else if (src === 'CompileScreeningEvidence') {
  out.decisionRationale = (scenario === 'Investigated')
    ? 'Evidence pack compiled for claim ' + (claimReference || '(unspecified)') + ': screening score 82, notification filed nine days after the accident, a lost earnings claim far exceeding the medical evidence, and no supporting police report on record.'
    : 'Evidence pack compiled for claim ' + (claimReference || '(unspecified)') + ': no adverse screening indicators identified.';
  out.explanation = out.decisionRationale;
} else if (src === 'ApplyLitigationEventCode') {
  out.litigationEventCode = 'LIT-' + runId;
  out.claimStatus = 'Litigation Event Recorded';
  out.explanation = 'Litigation event ' + out.litigationEventCode + ' recorded against claim ' + (claimReference || '(unspecified)') + ' following notice that proceedings have been issued.';
} else {
  out.explanation = 'Unrecognised requestSource: ' + src + '.';
}

return out;
